  ('San Diego Miramar College', '05100', 'Fire Technology', 'A.S. Degree', '2026-2027', 'https://sdccd.curriqunet.com/Catalog/Export?id=71&outlineId=20043', 'units', 25.5, 25.5, '{"blocks":[{"courses":[{"alternatives":[],"catalog_addition":false,"code":"FIPT 101","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"FIPT 102","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"FIPT 103","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"FIPT 104","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"FIPT 105","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"FIPT 120","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"EMGM 105A","units":7,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"EMGM 106","units":0.5,"units_max":null}],"minimum":null,"name":"COURSES REQUIRED FOR THE MAJOR","option_group":null,"rule":"all","stated":{"max":25.5,"min":25.5}}],"program":{"ge_pattern":null,"measure":"units","open_elective_units":null,"outcomes":["Identify minimum qualifications and entry level skills for firefighter hiring. The student will be able to describe the following elements: application process; written exam process; physical agility exam, oral interview, chief’s interview; background investigation; and fire fighter probationary process. Students will identify fire service history, culture and diversity.","Demonstrate the ability to analyze, appraise and evaluate fire and emergency incidents and identify components of emergency management and fire fighter safety including: Size-up, report on conditions, Incident Command System; RECEO; 10 Standard Firefighting Orders; 18 Situations that Shout “Watch Out “; and common factors associated with injuries and line of duty deaths.","Identify and comprehend laws, regulations, codes and standards that influence fire department operations, and id